import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

const Appointments = () => {
    const navigate = useNavigate();
    const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

    // Hardcoded mock data matching your mockup images
    // Using local paths from the 'public' folder
    const appointments = [
        { id: 1, title: "Soin visage", price: "3000 DA", duration: "1 hour", date: "15 July 2026", time: "14:00 - 15:00", status: "Pending Confirmation", statusColor: "yellow", image: "/soin.jpg" },
        { id: 2, title: "Massage relaxant", price: "4000 DA", duration: "1 h 30 min", date: "05 July 2026", time: "16:30 - 18:00", status: "Confirmed", statusColor: "green", image: "/massage.jpg" },
        { id: 3, title: "Épilation", price: "25000 DA", duration: "1 hour", date: "30 June 2026", time: "15:00 - 16:00", status: "Completed", statusColor: "blue", image: "/epilation.jpg" },
        { id: 4, title: "Coloration cheveux", price: "6000 DA", duration: "3 hour", date: "20 July 2026", time: "9:30 - 11:30", status: "Cancelled", statusColor: "red", image: "/coloration.jpg" },
    ];

    const handleLogout = () => {
        localStorage.removeItem('token');
        localStorage.removeItem('user');
        navigate('/login');
    };

    return (
        <div className="appointments-page">
            {/* ==================== NAVBAR ==================== */}
            <nav className="appointments-navbar">
                <div className="nav-logo">BeautyBook</div>

                {/* Desktop Menu */}
                <div className="nav-links-desktop">
                    <span className="nav-item" onClick={() => navigate('/services')}>🌸 Beauty treatments</span>
                    <span className="nav-item active">📅 Appointment</span>
                    <span className="nav-icon">🔔</span>
                    <span className="nav-icon" onClick={handleLogout} style={{cursor: 'pointer'}}>⚙️</span>
                </div>

                {/* Mobile Hamburger Menu Icon */}
                <div className="hamburger-icon" onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}>
                    ☰
                </div>
            </nav>

            {/* ==================== MOBILE SIDEBAR MENU ==================== */}
            <div className={`mobile-sidebar ${isMobileMenuOpen ? 'open' : ''}`}>
                <div className="sidebar-content">
                    <div className="sidebar-title">BeautyBook</div>
                    <div className="sidebar-item" onClick={() => { setIsMobileMenuOpen(false); navigate('/services'); }}>
                        🌸 Beauty treatments
                    </div>
                    <div className="sidebar-item active">📅 Appointment</div>
                    <div className="sidebar-icon-row">
                        <span>🔔</span>
                        <span onClick={() => { setIsMobileMenuOpen(false); handleLogout(); }}>⚙️</span>
                    </div>
                </div>
            </div>

            {/* ==================== MAIN CONTENT ==================== */}
            <div className="appointments-content">

                {/* Filter Pills */}
                <div className="filter-pills">
                    <button className="pill active">All appointment</button>
                    <button className="pill">Appointment confirmed</button>
                    <button className="pill">Discount offer</button>
                </div>

                {/* List of Appointments */}
                <div className="appointments-list">
                    {appointments.map((app) => (
                        <div key={app.id} className="appointment-card">
                            {/* Card Left: Image */}
                            <div className="card-image">
                                <img src={app.image} alt={app.title} />
                            </div>

                            {/* Card Middle: Details */}
                            <div className="card-details">
                                <h3 className="card-title">{app.title}</h3>
                                <div className="card-meta">
                                    <span>prix : {app.price}</span>
                                    <span>Duration : {app.duration}</span>
                                    <span>Date : {app.date}</span>
                                    <span>Time : {app.time}</span>
                                </div>
                            </div>

                            {/* Card Right: Action & Status */}
                            <div className="card-actions">
                                <button className="cancel-btn">Cancel Appointment if you want</button>
                                <div className="status-badge">
                                    {app.status}
                                    <span className={`status-dot ${app.statusColor}`}></span>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
};

export default Appointments;
